script:
"=== installing OpenCode via npm ==="
$env:Path = [System.Environment]::GetEnvironmentVariable("Path","Machine") + ";" + [System.Environment]::GetEnvironmentVariable("Path","User")
try {
  npm install -g opencode-ai 2>&1 | Select-Object -Last 5
  "npm install done"
} catch {
  "NPM FAILED: " + $_.Exception.Message
  exit 1
}
"=== verifying ==="
try {
  opencode --version
} catch {
  "opencode not in PATH, checking npm global bin"
  npm root -g
}
